.[tblEquipment].[QCDate],[dbo].[tblEquipment].[SecondaryStorageFlag],[dbo].[tblEquipment].[ManagedEquipmentFlag],[dbo].[tblEquipment].[FuelingType],[dbo].[tblEquipment].[UserData1],[dbo].[tblEquipment].[UserData2],[dbo].[tblEquipment].[UserData3],[dbo].[tblEquipment].[UserData4],[dbo].[tblEquipment].[UserData5],[dbo].[tblEquipment].[UserData6],[dbo].[tblEquipment].[UserData7],[dbo].[tblEquipment].[UserData8],[dbo].[tblEquipment].[UserData9],[dbo].[tblEquipment].[UserData10],[dbo].[tblEquipment].[UserData11],[dbo].[tblEquipment].[UserData12],[dbo].[tblEquipment].[UserData13],[dbo].[tblEquipment].[UserData14],[dbo].[tblEquipment].[UserData15],[dbo].[tblEquipment].[UserData16],[dbo].[tblEquipment].[UserData17],[dbo].[tblEquipment].[UserData18],[dbo].[tblEquipment].[UserData19],[dbo].[tblEquipment].[UserData20],[dbo].[tblEquipment].[UserData21],[dbo].[tblEquipment].[UserData22],[dbo].[tblEquipment].[UserData23],[dbo].[tblEquipment].[UserData24],[dbo].[tblEquipment].[EquipmentGuid],[dbo].[tblEquipment].[SiteGuid],[dbo].[tblEquipment].[CompanyGuid],[dbo].[tblEquipment].[ParentEquipmentGuid],[dbo].[tblEquipment].[EquipmentTypeGuid],[dbo].[tblEquipment].[FuelCardGuid],[dbo].[tblEquipment].[ProductGuid],[dbo].[tblEquipment].[AssignedToMeterGuid],[dbo].[tblEquipment].[AssetTrackingDeviceGuid],[dbo].[tblEquipment].[_MasterRecordGuid],[dbo].[tblEquipment].[HiddenDate],[dbo].[tblEquipment].[ScullyRequired], CT.UpdatedContext, CT.UpdatedRowVersion AS '_RowVersion'
